SELECT o.customer_id, CASE WHEN o.shipping_fee >= 36 THEN 'high' WHEN o.shipping_fee >= 10 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, COUNT(DISTINCT p.amount) AS unique_statuss FROM payments p RIGHT JOIN orders o ON p.order_id = o.id GROUP BY o.customer_id, CASE WHEN o.shipping_fee >= 36 THEN 'high' WHEN o.shipping_fee >= 10 THEN 'mid' ELSE 'low' END HAVING COUNT(DISTINCT p.amount) > 5 ORDER BY shipping_fee_bucket DESC, customer_id LIMIT 5;
